package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.village.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class VillageMigrationBehaviorGameTest{@GameTest public void migrationKeepsIdentityAndRecordsMove(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var manager=VillageManager.get(c.getLevel().getServer());var first=manager.all().iterator().next();var id=first.villageId();v.setPos(40,1,40);c.runAtTickTime(2,()->{TheWorldRemembers.processWorld(c.getLevel());if(manager.get(id)==null){c.fail("Village identity was lost");return;}var moves=VillageMigrationManager.get(c.getLevel().getServer()).get(id);if(moves.isEmpty()){c.fail("Migration was not recorded");return;}c.succeed();});});}}
